-- Bound temporary working data per canonical source. STABLE keeps every call
-- on the parent validation query's snapshot; the entire DO keeps the same3s limit.
create function pg_temp._ns_encoded_payload_mismatch(p_source_id text) returns boolean
language sql stable set search_path='' as $ns_payload$
select exists(with source_receipts as materialized (
 select source_id,discovery_report->'_fixtureObservations' receipts from public.nothingsports_fixture_sources where source_id=p_source_id
), fixture_inputs as materialized (
 select c.source_id,c.fixture_id,c.identity_keys,c.content_hash,c.updated_at,c.global_fixture,
  s.score,s.content_hash score_hash,s.first_completed_at,src.receipts->c.fixture_id fixture_receipt
 from public.nothingsports_fixture_current c join source_receipts src using(source_id)
 left join public.nothingsports_live_scores s using(source_id,fixture_id)
 where c.source_id=p_source_id
)
select 1 from nothingsports_fixture_read_private.global_encoded_rows w
 join fixture_inputs c using(source_id,fixture_id)
 where w.source_id=p_source_id and (row(w.base,w.identity_keys,w.base_hash,w.base_updated_at,w.score,w.score_hash,w.first_complete,w.receipt_s,w.receipt_t) is distinct from row(c.global_fixture,c.identity_keys,c.content_hash,c.updated_at,c.score,c.score_hash,c.first_completed_at,(c.fixture_receipt)->>'s',(c.fixture_receipt)->>'t') or (w.can_encode and (w.render_timezone<>current_setting('TimeZone') or statement_timestamp()<w.rendered_at or (case when w.row_text collate "C" is not distinct from (select row_to_json(p)::text from(select c.source_id,c.fixture_id,c.identity_keys,public.nothingsports_project_fixture_observations(c.global_fixture,c.score,c.fixture_receipt,c.first_completed_at) fixture)p) collate "C" then false else w.row_text::jsonb is distinct from (select row_to_json(p)::jsonb from(select c.source_id,c.fixture_id,c.identity_keys,public.nothingsports_project_fixture_observations(c.global_fixture,c.score,c.fixture_receipt,c.first_completed_at) fixture)p) end)))));
$ns_payload$;
do $payload_guard$ begin
 if exists(with source_keys as materialized (select distinct source_id from public.nothingsports_fixture_current)
 select 1 from source_keys s where pg_temp._ns_encoded_payload_mismatch(s.source_id)) then
  raise exception 'Encoded row payload/witness mismatch';
 end if;
end;$payload_guard$;
