 ), fixture_inputs as materialized (
 select c.source_id,c.fixture_id,c.identity_keys,c.content_hash,c.updated_at,c.global_fixture,
  s.score,s.content_hash score_hash,s.first_completed_at,src.receipts->c.fixture_id fixture_receipt
 from candidates k join public.nothingsports_fixture_current c using(source_id,fixture_id)
